from jsonb_to_recordset($wall_questions$[{"id":"u03_l07_q181","lesson_id":"u03_l07","difficulty":"medium","prompt":"لماذا كان بناء دور القرآن والمدارس والمكتبات من صور الوقف العلمي؟","options":[{"id":"o2","text":"لأنها تغني عن تعلم العلوم جميعها"},{"id":"o3","text":"لأنها تمنع استفادة الفقراء من التعليم"},{"id":"o4","text":"لأنها تقتصر على الزينة المعمارية"},{"id":"o1","text":"لأنها تنشر المعرفة وتحفظ العقل وتخدم المجتمع"}],"correct_id":"o1","explanation":"ذكر الكتاب دور الوقف العلمي في نشر العلم وتحقيق مقصد حفظ العقل.","page":134},{"id":"u03_l07_q184","lesson_id":"u03_l07","difficulty":"medium","prompt":"ما الخدمة التي يحققها الوقف الصحي إلى جانب تخفيف الأعباء المالية عن المرضى؟","options":[{"id":"o1","text":"توفير مرافق العلاج والرعاية الصحية"},{"id":"o4","text":"منع وصول الأدوية إلى المرضى"},{"id":"o3","text":"قصر العلاج على الأصحاء"},{"id":"o2","text":"تحويل المستشفيات إلى أماكن للترفيه فقط"}],"correct_id":"o1","explanation":"عرض الدرس بناء المستشفيات والخدمات الطبية من مجالات الوقف.","page":135},{"id":"u03_l07_q186","lesson_id":"u03_l07","difficulty":"medium","prompt":"ما الدلالة التنموية لوقف حفر الآبار وتجهيز المياه في طرق الحج قديمًا؟","options":[{"id":"o1","text":"تيسير حاجات المسافرين وتوفير مورد أساسي للحياة"},{"id":"o3","text":"حصر المنفعة في شخص الواقف"},{"id":"o2","text":"منع الحركة بين المدن"},{"id":"o4","text":"إيقاف المرافق العامة عن الخدمة"}],"correct_id":"o1","explanation":"أورد الدرس وقفية زبيدة في حفر الآبار وإنشاء البرك والقنوات.","page":136},{"id":"u03_l07_q188","lesson_id":"u03_l07","difficulty":"medium","prompt":"من أنشأ موقعًا يتيح دروسًا وكتبًا مفيدة مجانًا على نحو مستمر؛ أي مجال حديث يندرج فيه عمله؟","options":[{"id":"o1","text":"الوقف الإلكتروني لخدمة العلم"},{"id":"o2","text":"الوقف العسكري لتزويد الجيوش"},{"id":"o3","text":"الوقف الصحي لخدمة المستشفى فقط"},{"id":"o4","text":"الوصية المحرمة للوارث بالضرورة"}],"correct_id":"o1","explanation":"ذكر إثراء الكتاب إنشاء مواقع للكتب والدروس والمحاضرات بوصفه صورة وقف إلكتروني.","page":137},{"id":"u04_l01_q091","lesson_id":"u04_l01","difficulty":"medium","prompt":"لماذا بدأ النبي ﷺ سؤاله للصحابة عن المفلس مع أنه يعلم المعنى الذي سيبينه؟","options":[{"id":"o1","text":"لإثارة التفكير وشد الانتباه"},{"id":"o2","text":"لأنه كان يبحث عن معنى لغوي مجهول"},{"id":"o4","text":"للاقتصار على التعريف الاقتصادي للإفلاس"},{"id":"o3","text":"لاختبار قدرتهم على عد النقود"}],"correct_id":"o1","explanation":"بيّن الدرس أن السؤال أداة تعليمية لجذب الانتباه قبل عرض المعنى الأعمق.","page":141},{"id":"u04_l01_q094","lesson_id":"u04_l01","difficulty":"medium","prompt":"لماذا نُهي عن القذف في شرح الحديث؟","options":[{"id":"o3","text":"لأن الكلمة لا تؤثر في حق الإنسان"},{"id":"o4","text":"لأنه يتعلق بالبيع والشراء فقط"},{"id":"o2","text":"لأن الألقاب الحسنة ممنوعة"},{"id":"o1","text":"حماية أعراض الناس من الاتهام الباطل"}],"correct_id":"o1","explanation":"عرّف الكتاب القذف باعتداء على أعراض الأبرياء.","page":142},{"id":"u04_l01_q107","lesson_id":"u04_l01","difficulty":"medium","prompt":"ما الفرق بين المفلس في المعنى الشائع عند الصحابة والمفلس في الحديث؟","options":[{"id":"o2","text":"الأول كثير المال والثاني كثير التجارة"},{"id":"o1","text":"الأول لا مال لديه والثاني يخسر ثواب عمله باعتدائه على حقوق الناس"},{"id":"o4","text":"الأول يسيء إلى الناس حتمًا والثاني لا يخطئ"},{"id":"o3","text":"كلاهما لا يفعل أعمالًا صالحة مطلقًا"}],"correct_id":"o1","explanation":"انتقل الحديث من الإفلاس الدنيوي بفقد المال إلى الإفلاس الأخروي المتعلق بالمظالم.","page":141},{"id":"u04_l01_q114","lesson_id":"u04_l01","difficulty":"medium","prompt":"طالب يكثر من الطاعات ويستهزئ بزملائه، ما الخلل الذي يكشفه هذا الموقف في ضوء الحديث؟","options":[{"id":"o2","text":"المبالغة في أداء الحقوق الاجتماعية"},{"id":"o1","text":"إهمال حقوق الناس مع الانشغال بالعبادة"},{"id":"o4","text":"الجمع الصحيح بين الطاعة وحسن الخلق"},{"id":"o3","text":"الحرص على أداء الواجبات المالية"}],"correct_id":"o1","explanation":"حذّر الحديث من أن الإساءة إلى الآخرين تذهب بأجر الطاعات مهما كثرت.","page":142},{"id":"u04_l01_q116","lesson_id":"u04_l01","difficulty":"medium","prompt":"ما وجه الشبه بين إتلاف الأشجار الحرجية والعبث بالحدائق العامة؟","options":[{"id":"o1","text":"كلاهما اعتداء على مصالح وحقوق عامة"},{"id":"o4","text":"كلاهما صورة من الزكاة الواجبة"},{"id":"o3","text":"كلاهما وسيلة لحفظ مرافق المجتمع"},{"id":"o2","text":"كلاهما تصرف في ملك خاص دون أثر عام"}],"correct_id":"o1","explanation":"أورد الكتاب الاعتداء على الأشجار الحرجية والحدائق مثالين على الإضرار بالحقوق العامة.","page":143},{"id":"u04_l01_q118","lesson_id":"u04_l01","difficulty":"hard","prompt":"ما الاستنتاج الأدق من اجتماع ذكر الصلاة والصيام مع التعدي على الأموال والأعراض في الحديث؟","options":[{"id":"o4","text":"أن أعمال البر لا صلة لها بالتعامل مع الناس"},{"id":"o1","text":"الطاعات لا تُسقط المسؤولية عن حقوق الآخرين"},{"id":"o3","text":"أن حقوق الآخرين منفصلة تمامًا عن التقويم الأخلاقي"},{"id":"o2","text":"أن النوافل تبيح الاعتداء على حقوق الآخرين"}],"correct_id":"o1","explanation":"عرض الحديث كثرة الطاعات مع وجود مظالم تبقى مؤثرة في الحساب.","page":142},{"id":"u04_l01_q121","lesson_id":"u04_l01","difficulty":"easy","prompt":"ما الغرض التعليمي من سؤال النبي ﷺ أصحابه عن معنى «المفلس» قبل بيانه؟","options":[{"id":"o2","text":"الاستفهام عن مال كل صحابي على حدة"},{"id":"o3","text":"تحديد قيمة الدراهم في السوق"},{"id":"o4","text":"تقرير أن الفقر يمنع العبادة"},{"id":"o1","text":"إثارة تفكيرهم وشد انتباههم إلى المعنى المقصود"}],"correct_id":"o1","explanation":"ذكر الدرس أن سؤال النبي ﷺ كان لإثارة التفكير وشد الانتباه لا لطلب المعلومة.","page":141},{"id":"u04_l01_q122","lesson_id":"u04_l01","difficulty":"medium","prompt":"كيف يختلف إفلاس الدنيا الذي ذكره الصحابة عن الإفلاس في الحديث الشريف؟","options":[{"id":"o4","text":"كلاهما يعني العجز عن العمل فقط"},{"id":"o2","text":"الأول فقد حسنات الصوم والثاني فقد الدراهم فقط"},{"id":"o3","text":"كلاهما يعني عدم أداء الصلاة وحدها"},{"id":"o1","text":"الأول فقد المال والمتاع والثاني ضياع ثواب الأعمال بسبب ظلم الناس"}],"correct_id":"o1","explanation":"ميّز النبي ﷺ بين المعنى الشائع للإفلاس ومعناه الأخروي المرتبط بحقوق العباد.","page":141},{"id":"u04_l01_q126","lesson_id":"u04_l01","difficulty":"hard","prompt":"ما الخطأ في استنتاج من يقول: «ما دمت لم آخذ مالًا من غيري، فلا يمكن أن أكون قد ظلمته»؟","options":[{"id":"o2","text":"إقراره بأن المال حق لصاحبه"},{"id":"o1","text":"حصر الظلم في المال وإغفال الاعتداء على السمعة والحقوق الأخرى"},{"id":"o3","text":"تمييزه بين الفقر والغنى"},{"id":"o4","text":"اهتمامه بردّ الأموال لأصحابها"}],"correct_id":"o1","explanation":"عدّد الحديث صورًا من الظلم تتعلق بالقول والمال وغيرها، لا بالمال وحده.","page":142},{"id":"u04_l01_q127","lesson_id":"u04_l01","difficulty":"medium","prompt":"ما العلاقة بين صيانة الأعراض وتجنّب الإفلاس الأخروي وفق شرح الحديث؟","options":[{"id":"o1","text":"الاعتداء على سمعة الناس من المظالم التي تُضيّع الحسنات"},{"id":"o4","text":"الحديث يقتصر على الاعتداء على المال العام"},{"id":"o3","text":"حماية السمعة تعني منع كل نصيحة"},{"id":"o2","text":"صيانة الأعراض شأن مالي لا علاقة له بالأخلاق"}],"correct_id":"o1","explanation":"بيّن الشرح أن الاعتداء على أعراض الناس من أسباب الإفلاس يوم القيامة.","page":142},{"id":"u04_l01_q130","lesson_id":"u04_l01","difficulty":"hard","prompt":"شخص رد مالًا أخذه بغير حق لكنه استمر في السخرية ممن أساء إليه. ما التقييم الأدق؟","options":[{"id":"o4","text":"يجوز له تعويض ظلم المال بالإساءة اللفظية"},{"id":"o2","text":"زالت جميع المظالم بمجرد رد المال"},{"id":"o3","text":"السخرية لا تدخل في حقوق الناس"},{"id":"o1","text":"عالج جانب المال ولم يتوقف عن ظلم يتعلق بالكرامة واللسان"}],"correct_id":"o1","explanation":"يتطلب تجنب الإفلاس صيانة مختلف حقوق الناس لا جانبًا واحدًا منها.","page":143},{"id":"u04_l01_q131","lesson_id":"u04_l01","difficulty":"medium","prompt":"سأل النبي ﷺ أصحابه عن معنى المفلس مع علمه بجوابهم الشائع؛ فما المقصد التربوي من هذا السؤال؟","options":[{"id":"o4","text":"تأجيل شرح الحديث إلى وقت آخر"},{"id":"o3","text":"الاعتماد على التعريف المالي وحده"},{"id":"o1","text":"إثارة التفكير وشد الانتباه إلى معنى آخر للإفلاس"},{"id":"o2","text":"جمع معلومات عن تجارة الصحابة"}],"correct_id":"o1","explanation":"يبيّن الدرس أن السؤال كان لإثارة تفكير الصحابة وشد انتباههم لا لمجرد الاستفهام.","page":141},{"id":"u04_l01_q137","lesson_id":"u04_l01","difficulty":"medium","prompt":"ما وجه الاختلاف بين الوفاء بحقوق العباد في الدنيا والوفاء بها يوم القيامة؟","options":[{"id":"o1","text":"الجزاء الأخروي مرتبط بالحسنات والسيئات لا بالدراهم والدنانير"},{"id":"o2","text":"الحقوق في الآخرة تؤدى بالرواتب المالية"},{"id":"o4","text":"حقوق الآخرين تسقط لمجرد كثرة العبادة"},{"id":"o3","text":"لا يُحاسب الإنسان على حقوق الناس"}],"correct_id":"o1","explanation":"ذكر الدرس أن الوفاء يوم القيامة لا يكون بالنقود بل من الحسنات والسيئات.","page":143},{"id":"u04_l01_q138","lesson_id":"u04_l01","difficulty":"medium","prompt":"ما الصفة المشتركة بين العبث بشبكة المياه العامة والاعتداء على حديقة عامة؟","options":[{"id":"o1","text":"الإضرار بحقوق عامة يشترك الناس في الانتفاع بها"},{"id":"o4","text":"اعتبار الفعل صدقة جارية"},{"id":"o3","text":"الاقتصار على نزاع مالي شخصي"},{"id":"o2","text":"عدم وجود أي حق للناس فيهما"}],"correct_id":"o1","explanation":"ذكر الإثراء العبث بشبكات المياه والكهرباء والحدائق العامة أمثلة للاعتداء على الحقوق العامة.","page":143},{"id":"u04_l01_q141","lesson_id":"u04_l01","difficulty":"medium","prompt":"ما الهدف التعليمي الذي تحقّق بسؤال النبي ﷺ أصحابه عن معنى المُفلِس قبل بيان المعنى المقصود؟","options":[{"id":"o3","text":"اختبار قدرتهم على حفظ الأرقام"},{"id":"o1","text":"استثارة تفكيرهم وشد انتباههم إلى المعنى الأخروي"},{"id":"o2","text":"التأكد من أسماء كل الصحابة"},{"id":"o4","text":"بيان حكم البيع والشراء فقط"}],"correct_id":"o1","explanation":"صرّح الدرس بأن سؤال النبي ﷺ كان لإثارة التفكير وجذب الانتباه لا لطلب المعلومة.","page":141},{"id":"u04_l01_q145","lesson_id":"u04_l01","difficulty":"medium","prompt":"ما وجه الاختلاف في الحق الذي يقع عليه الاعتداء بين القذف وأكل أموال الناس بالباطل؟","options":[{"id":"o4","text":"كلاهما يتعلق بحق الطريق فقط"},{"id":"o1","text":"الأول يمس العرض والثاني يمس المال"},{"id":"o3","text":"كلاهما يتعلق بالقراءة وحدها"},{"id":"o2","text":"الأول يمس المال والثاني يمس العرض"}],"correct_id":"o1","explanation":"صنّف الكتاب القذف اعتداء على الأعراض وأكل المال بالباطل اعتداء على الأموال.","page":142},{"id":"u04_l01_q147","lesson_id":"u04_l01","difficulty":"medium","prompt":"لماذا يُعدّ الإضرار بمرافق الماء العامة داخلًا في مضمون التحذير من الإفلاس الأخروي؟","options":[{"id":"o3","text":"لأنه لا يؤثر إلا في الممتلكات الخاصة"},{"id":"o1","text":"لأنه اعتداء على حقوق عامة ينتفع بها الناس"},{"id":"o4","text":"لأن الإضرار بها يُصلح الاقتصاد"},{"id":"o2","text":"لأن المرافق العامة لا صاحب لها"}],"correct_id":"o1","explanation":"نص الدرس على أن العبث بخطوط الماء والكهرباء والمرافق العامة اعتداء على الحقوق العامة.","page":143},{"id":"u04_l01_q156","lesson_id":"u04_l01","difficulty":"hard","prompt":"إذا اعتقد إنسان أن حسناته الشخصية تعفيه من إعادة الحقوق إلى أصحابها، فما الذي يصححه حديث المفلس؟","options":[{"id":"o1","text":"أن حقوق الناس لا تسقط بكثرة العبادات مع استمرار الاعتداء"},{"id":"o3","text":"أن الاعتداء على الحق العام ليس له أثر"},{"id":"o4","text":"أن رد الحقوق مطلوب من أصحاب المال فقط"},{"id":"o2","text":"أن ظلم الناس يُعد إحسانًا إذا صدر من متعبد"}],"correct_id":"o1","explanation":"حذر الحديث من خسارة أثر الحسنات بسبب الاعتداء على حقوق الناس.","page":143},{"id":"u04_l01_q163","lesson_id":"u04_l01","difficulty":"hard","prompt":"صاحب متجر يرفع سعر سلعة باستغلال حاجة الناس ويظلم المشترين؛ تحت أي عنوان يندرج الفعل في شرح الحديث؟","options":[{"id":"o2","text":"المداومة على صلاة التطوع"},{"id":"o3","text":"صيانة حق الطريق"},{"id":"o1","text":"أكل أموال الناس بالباطل والاعتداء على الحقوق"},{"id":"o4","text":"المساهمة في التكافل الاجتماعي"}],"correct_id":"o1","explanation":"ذكر الدرس الاستغلال ورفع الأسعار مع صور الاعتداء على الأموال.","page":142},{"id":"u04_l01_q164","lesson_id":"u04_l01","difficulty":"medium","prompt":"لماذا يعد الإيذاء المعنوي للناس ضمن المخالفات التي يحذر منها حديث المفلس؟","options":[{"id":"o4","text":"لأن الحقوق لا تشمل سمعة الإنسان"},{"id":"o2","text":"لأنه لا يؤثر مطلقًا في الناس"},{"id":"o1","text":"لأن الحقوق تشمل الكرامة والعرض لا المال والجسد فقط"},{"id":"o3","text":"لأن السخرية واجبة لإصلاح المجتمع"}],"correct_id":"o1","explanation":"بيّن الكتاب أن الإيذاء قد يكون معنويًا بالسخرية والغيبة وغيرهما.","page":142},{"id":"u04_l01_q166","lesson_id":"u04_l01","difficulty":"medium","prompt":"كيف يختلف الوفاء بحقوق الناس في الآخرة عنه في المعاملات المالية بالدنيا؟","options":[{"id":"o3","text":"تسقط فيه المظالم جميعها دون حساب"},{"id":"o2","text":"يتم بتبادل الأوراق النقدية فقط"},{"id":"o1","text":"يكون بالعدل في الحساب من الحسنات والسيئات لا بالدراهم والدنانير"},{"id":"o4","text":"يتوقف على ثراء الإنسان في الدنيا"}],"correct_id":"o1","explanation":"بيّن الدرس أن حقوق العباد تؤدى في الآخرة وفق العدل الإلهي لا بالنقود.","page":143},{"id":"u04_l01_q173","lesson_id":"u04_l01","difficulty":"medium","prompt":"شخص يصلي ويصوم لكنه يستهين بحقوق الآخرين، فأي حقيقة يوضحها حديث المفلس؟","options":[{"id":"o1","text":"أن أداء العبادات لا يبيح الاعتداء على الناس"},{"id":"o4","text":"أن العبادات تُلغي وجوب الوفاء بالحقوق"},{"id":"o3","text":"أن حسن الخلق ليس له أثر في الحساب"},{"id":"o2","text":"أن حقوق الناس تسقط بكثرة الصيام"}],"correct_id":"o1","explanation":"نبّه الدرس إلى أن ظلم العباد قد يذهب بثواب أعمال صالحة كثيرة.","page":142},{"id":"u04_l01_q181","lesson_id":"u04_l01","difficulty":"medium","prompt":"لماذا بدأ النبي ﷺ حديث المفلس بسؤال أصحابه عن معناه بدل أن يبدأ بالتعريف مباشرة؟","options":[{"id":"o4","text":"لأنه أراد حصر الحديث بأصحاب المال"},{"id":"o2","text":"لأنه لم يكن يعرف معنى الكلمة في اللغة"},{"id":"o1","text":"ليثير انتباههم ويهيئهم لتصحيح تصور مألوف"},{"id":"o3","text":"لأن حديثه كان عن التجارة وحدها"}],"correct_id":"o1","explanation":"شرح الدرس أن سؤال النبي ﷺ كان للتشويق وتنبيه الفكر لا لطلب معلومة يجهلها.","page":141},{"id":"u04_l01_q183","lesson_id":"u04_l01","difficulty":"medium","prompt":"ماذا نتعلم من اجتماع الصلاة والزكاة والصيام في وصف شخص اعتدى على غيره؟","options":[{"id":"o2","text":"أن حقوق الناس تسقط كلما زادت النوافل"},{"id":"o1","text":"أن أداء العبادات لا يبيح ظلم الناس وانتهاك حقوقهم"},{"id":"o4","text":"أن الاعتداء على الغير مباح مع الصدقة"},{"id":"o3","text":"أن العبادات لا شأن لها بالأخلاق أبدًا"}],"correct_id":"o1","explanation":"بين الدرس أن كثرة الحسنات لا تمنع استيفاء حقوق المظلومين.","page":142},{"id":"u04_l01_q185","lesson_id":"u04_l01","difficulty":"medium","prompt":"لماذا يكون وفاء المظالم في الآخرة بالحسنات والسيئات لا بالمال الدنيوي؟","options":[{"id":"o2","text":"لأن المال شرط لقبول الحساب في الآخرة"},{"id":"o3","text":"لأن الحقوق تسقط تلقائيًا بعد الموت"},{"id":"o4","text":"لأن صاحب المال وحده يُسأل عن سلوكه"},{"id":"o1","text":"لأن الجزاء الأخروي يختلف عن وسائل الوفاء في الحياة الدنيا"}],"correct_id":"o1","explanation":"نص الدرس على أن وفاء الحقوق يوم القيامة لا يكون بالدرهم والدينار.","page":143},{"id":"u04_l02_q108","lesson_id":"u04_l02","difficulty":"medium","prompt":"كيف يسهم رفض التقليد الأعمى والخرافات في حفظ العقل؟","options":[{"id":"o2","text":"بتعطيل التفكير في الوقائع"},{"id":"o3","text":"بمنع طلب العلم النافع"},{"id":"o1","text":"بإتاحة التفكير الواعي بعيدًا عن الأوهام والتصورات الفاسدة"},{"id":"o4","text":"بالاستعاضة عن الأدلة بالشائعات"}],"correct_id":"o1","explanation":"دعا الدرس إلى تحرير العقل من الأوهام والتعصب والتقليد الأعمى.","page":148},{"id":"u04_l02_q113","lesson_id":"u04_l02","difficulty":"medium","prompt":"أي وسيلة لحفظ الدين تُظهر أهمية الأسلوب الحكيم في التعامل مع الناس؟","options":[{"id":"o3","text":"ترك تعليم أركان الإيمان"},{"id":"o4","text":"حصر عبادة الله في العادات الاجتماعية"},{"id":"o2","text":"إلغاء الحوار مع المخالف"},{"id":"o1","text":"الدعوة بالحكمة والموعظة الحسنة"}],"correct_id":"o1","explanation":"ذكر الدرس الدعوة بالحكمة والموعظة الحسنة وسيلة لحفظ الدين.","page":146},{"id":"u04_l02_q120","lesson_id":"u04_l02","difficulty":"hard","prompt":"ما التوصيف الصحيح لعملٍ يرفع الحرج عن المسافر دون أن يتوقف عليه أصل حفظ الدين؟","options":[{"id":"o2","text":"مصلحة ضرورية ينهدم أصل الحياة دونها"},{"id":"o1","text":"مصلحة حاجية تيسّر أداء التكليف"},{"id":"o4","text":"مخالفة لأحكام العبادات في كل حال"},{"id":"o3","text":"مصلحة تحسينـية لا تتصل بالمشقة"}],"correct_id":"o1","explanation":"مثّل الدرس للحاجيات بالرخص الشرعية التي ترفع المشقة عن المسافر.","page":150},{"id":"u04_l02_q125","lesson_id":"u04_l02","difficulty":"hard","prompt":"ما الذي يجمع بين تجنّب الاعتداء على الآخرين والحفاظ على الصحة العامة في مقصد حفظ النفس؟","options":[{"id":"o1","text":"صيانة الحياة ومنع أسباب الضرر قبل وقوعها"},{"id":"o2","text":"قصر حفظ النفس على العلاج بعد وقوع الضرر"},{"id":"o3","text":"تقديم المصلحة المالية على كل حياة"},{"id":"o4","text":"اعتبار حفظ النفس مسؤولية الطبيب وحده"}],"correct_id":"o1","explanation":"يتناول مقصد حفظ النفس حماية الأرواح ومنع الاعتداء وتعزيز الوقاية والرعاية.","page":147},{"id":"u04_l02_q126","lesson_id":"u04_l02","difficulty":"medium","prompt":"كيف يتكامل طلب العلم مع التفكر في الكون في مقصد حفظ العقل؟","options":[{"id":"o3","text":"طلب العلم ينفي الحاجة إلى استعمال العقل"},{"id":"o2","text":"كلاهما يهدف إلى تعطيل التفكير النقدي"},{"id":"o4","text":"التفكر يمنع اكتساب المعرفة"},{"id":"o1","text":"كلاهما ينمّي التفكير السليم ويعين على إدراك الحقائق"}],"correct_id":"o1","explanation":"جعل الدرس الدعوة إلى التفكر وطلب العلم من وسائل حفظ العقل.","page":148},{"id":"u04_l02_q127","lesson_id":"u04_l02","difficulty":"hard","prompt":"طالبة تراجع خبرًا غير موثوق قبل نشره بدل اتباعه تقليدًا أعمى. إلى أي جانب من حفظ العقل يقترب سلوكها؟","options":[{"id":"o1","text":"تحرير التفكير من الأوهام والتصورات الفاسدة"},{"id":"o4","text":"نشر ما يوافق الرأي دون تمحيص"},{"id":"o2","text":"الامتناع عن الاستفادة من المعرفة"},{"id":"o3","text":"إلغاء دور الأدلة في الحكم"}],"correct_id":"o1","explanation":"يدعو الدرس إلى تحرير العقل من الأوهام والتقليد الأعمى والتصورات الفاسدة.","page":148},{"id":"u04_l02_q128","lesson_id":"u04_l02","difficulty":"medium","prompt":"لماذا يجمع حفظ المال بين الحث على العمل وتحريم الحصول عليه بالباطل؟","options":[{"id":"o2","text":"لأن مجرد امتلاك المال محرّم"},{"id":"o1","text":"ليكون اكتساب المال مشروعًا مع صيانة حقوق الآخرين"},{"id":"o4","text":"لأن الغاية تبيح أي وسيلة لكسب المال"},{"id":"o3","text":"لأن العمل يعفي صاحبه من حقوق الناس"}],"correct_id":"o1","explanation":"بيّن الدرس مشروعية السعي للكسب ووجوب تجنب أخذ المال بطرق غير مشروعة.","page":149},{"id":"u04_l02_q130","lesson_id":"u04_l02","difficulty":"medium","prompt":"لماذا لا تُعد آداب الطعام والشراب من الضروريات في هذا التقسيم؟","options":[{"id":"o2","text":"لأن الالتزام بها يمنع تناول الطعام"},{"id":"o1","text":"لأنها من التحسينيات التي تكمّل السلوك وتزيده حسنًا"},{"id":"o3","text":"لأنها تُسقط وجوب حفظ النفس"},{"id":"o4","text":"لأنها تُعد من الرخص الخاصة بالسفر"}],"correct_id":"o1","explanation":"أورد الكتاب الأخذ بآداب الطعام والشراب ضمن أمثلة التحسينيات.","page":150},{"id":"u04_l02_q142","lesson_id":"u04_l02","difficulty":"medium","prompt":"كيف ترتبط الدعوة بالحكمة والموعظة الحسنة بمقصد حفظ الدين؟","options":[{"id":"o4","text":"تمنع توضيح الأحكام للناس"},{"id":"o3","text":"تجعل التدين شأنًا لا يتصل بالأخلاق"},{"id":"o2","text":"تستبدل أداء العبادات بالحوار فقط"},{"id":"o1","text":"تدعو إلى الإيمان والالتزام بوسيلة مناسبة"}],"correct_id":"o1","explanation":"عدّ الكتاب الدعوة بالحكمة والموعظة الحسنة ضمن وسائل حفظ الدين.","page":146},{"id":"u04_l02_q145","lesson_id":"u04_l02","difficulty":"medium","prompt":"عامل يحصل على رزقه بجهده الحلال ويبتعد عن الرشوة؛ أي مقصد يحققه السلوكان معًا؟","options":[{"id":"o3","text":"حفظ النفس عن طريق السفر"},{"id":"o1","text":"حفظ المال باكتسابه المشروع وحمايته من الفساد"},{"id":"o4","text":"مرتبة التحسينيات فقط"},{"id":"o2","text":"حفظ النسل فقط"}],"correct_id":"o1","explanation":"جمع الدرس تحت حفظ المال بين الحث على العمل المشروع وتحريم أخذ الأموال بغير حق.","page":149},{"id":"u04_l02_q146","lesson_id":"u04_l02","difficulty":"hard","prompt":"لماذا لا يؤدي غياب بعض الرخص الشرعية إلى زوال أصل المقاصد مع أنه يشق على الناس؟","options":[{"id":"o4","text":"لأن مشقة الناس لا تُراعى أصلًا"},{"id":"o2","text":"لأن الحاجيات تعني أوامر محرمة دائمًا"},{"id":"o1","text":"لأن الرخص من الحاجيات التي ترفع الحرج لا من الضروريات التي يقوم عليها أصل الحياة"},{"id":"o3","text":"لأن التيسير يخالف مقاصد الشريعة"}],"correct_id":"o1","explanation":"فرّق الكتاب بين الضروريات الضرورية لقيام المقاصد والحاجيات التي يسبب فقدها المشقة والحرج.","page":150},{"id":"u04_l02_q147","lesson_id":"u04_l02","difficulty":"medium","prompt":"أي حكم من الأمثلة الآتية يجمع بين التقرب إلى الله وتحسين هيئة السلوك دون أن يتوقف عليه أصل قيام الحياة؟","options":[{"id":"o2","text":"حفظ الأرواح ومنع الاعتداء عليها"},{"id":"o4","text":"منع أكل أموال الناس بالباطل"},{"id":"o3","text":"وجوب أصل الصلاة المفروضة"},{"id":"o1","text":"أداء النوافل ومراعاة آداب الحديث"}],"correct_id":"o1","explanation":"جعل الكتاب النوافل وحسن الآداب من أمثلة مرتبة التحسينيات.","page":150},{"id":"u04_l02_q156","lesson_id":"u04_l02","difficulty":"medium","prompt":"أين يندرج الحث على العمل واكتساب المال بالحلال ضمن المقاصد الكلية؟","options":[{"id":"o1","text":"حفظ المال وتنميته بالوسائل المشروعة"},{"id":"o4","text":"شرح أحوال العدة"},{"id":"o2","text":"حفظ العقل من الخرافات فقط"},{"id":"o3","text":"تخفيف صلاة الجماعة"}],"correct_id":"o1","explanation":"وضع الدرس العمل والكسب المشروع من وسائل المحافظة على المال.","page":149},{"id":"u04_l02_q157","lesson_id":"u04_l02","difficulty":"hard","prompt":"لماذا لا يعني عدم تحقق الحاجيات زوال مقاصد الحياة كلها وفق مراتب الشريعة؟","options":[{"id":"o3","text":"لأن التحسينيات وحدها تُبقي الحياة قائمة"},{"id":"o1","text":"لأن غيابها يوقع في الحرج والمشقة دون انعدام الضروريات"},{"id":"o4","text":"لأن كل حاجية واجبة على كل شخص بنفس الصورة"},{"id":"o2","text":"لأن الحاجيات والضروريات متطابقتان تمامًا"}],"correct_id":"o1","explanation":"ميز الكتاب رتبة الحاجيات بأنها ترفع الحرج بخلاف الضروريات التي تقوم عليها الحياة.","page":150},{"id":"u04_l02_q164","lesson_id":"u04_l02","difficulty":"medium","prompt":"كيف يُطبق مقصد حفظ النفس في السلوك الصحي اليومي؟","options":[{"id":"o2","text":"رفض جميع وسائل الوقاية الحديثة"},{"id":"o1","text":"العناية بالغذاء النافع والوقاية والعلاج عند الحاجة"},{"id":"o3","text":"ترك علاج المرض على سبيل الإهمال"},{"id":"o4","text":"إهمال السلامة عند ممارسة الأنشطة"}],"correct_id":"o1","explanation":"أورد الدرس الطعام الصحي والتداوي والفحوص والتطعيم من وسائل حفظ النفس.","page":147},{"id":"u04_l02_q165","lesson_id":"u04_l02","difficulty":"medium","prompt":"ما سبب ارتباط حفظ العقل بمسؤولية الإنسان عن أفعاله في الشريعة؟","options":[{"id":"o1","text":"لأن العقل مناط فهم التكليف والقدرة على التفكير"},{"id":"o4","text":"لأن العلم والتعلم يناقضان حفظ العقل"},{"id":"o3","text":"لأن كل مخلوق يُكلّف بما لا يدرك"},{"id":"o2","text":"لأن العقل لا صلة له بفهم الأحكام"}],"correct_id":"o1","explanation":"شرح الكتاب صلة العقل بالتكليف والتمييز والتخطيط.","page":148},{"id":"u04_l02_q168","lesson_id":"u04_l02","difficulty":"hard","prompt":"ما الذي يميز التحسينيات عن الحاجيات في مراتب المقاصد؟","options":[{"id":"o4","text":"التحسينيات تمنع تحقيق أي مصلحة"},{"id":"o3","text":"الحاجيات محصورة في المظهر الخارجي"},{"id":"o2","text":"التحسينيات تلغي جميع الضروريات"},{"id":"o1","text":"التحسينيات تزيد جمال السلوك وآدابه بينما الحاجيات ترفع الحرج والمشقة"}],"correct_id":"o1","explanation":"شرح الدرس التحسينيات كمحاسن العادات والحاجيات كتيسير يرفع الحرج.","page":150},{"id":"u04_l02_q177","lesson_id":"u04_l02","difficulty":"medium","prompt":"ما الفرق بين الحاجيات والضروريات في مراتب مقاصد الشريعة؟","options":[{"id":"o1","text":"فقد الحاجيات يجلب المشقة بينما فقد الضروريات يخل بنظام الحياة"},{"id":"o3","text":"الضروريات تخص الزينة دون مصالح الناس"},{"id":"o2","text":"الحاجيات أهم من الضروريات في كل الأحوال"},{"id":"o4","text":"الحاجيات لا علاقة لها بالتخفيف والتيسير"}],"correct_id":"o1","explanation":"فرّق الكتاب بين اختلال نظام الحياة بفقد الضروريات والمشقة بفقد الحاجيات.","page":150},{"id":"u04_l02_q187","lesson_id":"u04_l02","difficulty":"medium","prompt":"ما الذي يميز الحاجيات عن الضروريات في تقسيم مقاصد الشريعة؟","options":[{"id":"o2","text":"فقد الحاجيات يبطل وجود المجتمع بالضرورة"},{"id":"o4","text":"الضروريات تتعلق بآداب المظهر وحدها"},{"id":"o1","text":"فقد الحاجيات يسبب مشقة وحرجًا دون اختلال أصل الحياة"},{"id":"o3","text":"الحاجيات لا صلة لها بتخفيف التكليف"}],"correct_id":"o1","explanation":"فسر الكتاب الحاجيات بما يرفع المشقة مع بقاء نظام الحياة عند فقدها.","page":150},{"id":"u04_l02_q188","lesson_id":"u04_l02","difficulty":"hard","prompt":"أي ترتيب للمقاصد يناسب أمثلة: منع الضرر الجسيم ثم رخصة المسافر ثم آداب الطعام؟","options":[{"id":"o2","text":"تحسينيات ثم ضروريات ثم حاجيات"},{"id":"o1","text":"ضروريات ثم حاجيات ثم تحسينيات"},{"id":"o3","text":"حاجيات ثم تحسينيات ثم ضروريات"},{"id":"o4","text":"ضروريات ثم تحسينيات ثم حاجيات"}],"correct_id":"o1","explanation":"عرض الدرس هذه المجالات وفق أهميتها في مراتب الضروريات والحاجيات والتحسينيات.","page":150},{"id":"u04_l03_q106","lesson_id":"u04_l03","difficulty":"medium","prompt":"كيف يساهم تعميق استشعار رقابة الله تعالى في الوقاية من الجريمة؟","options":[{"id":"o4","text":"بإجازة التجاوزات عند غياب الناس"},{"id":"o2","text":"بجعل القانون بلا وظيفة في المجتمع"},{"id":"o3","text":"بإغناء الإنسان عن أداء واجباته"},{"id":"o1","text":"بتهذيب النفس وتقوية التقوى والابتعاد عن المعاصي"}],"correct_id":"o1","explanation":"ذكر الدرس تعميق الإيمان واستشعار الرقابة الإلهية من التدابير الوقائية.","page":155},{"id":"u04_l03_q115","lesson_id":"u04_l03","difficulty":"medium","prompt":"ما العلاقة بين توفير فرص العمل والتكافل الاجتماعي والوقاية من بعض الجرائم؟","options":[{"id":"o2","text":"إضعاف حياة المجتمع الاقتصادية"},{"id":"o1","text":"معالجة أسباب اقتصادية واجتماعية قد تدفع إلى المخالفة"},{"id":"o4","text":"إلغاء قيمة العمل من حياة الفرد"},{"id":"o3","text":"تشجيع انتهاك أموال الآخرين"}],"correct_id":"o1","explanation":"ذكر الدرس العمل والتكافل بوصفهما وسيلتين لمعالجة أسباب الجريمة قبل وقوعها.","page":156},{"id":"u04_l03_q116","lesson_id":"u04_l03","difficulty":"medium","prompt":"لماذا يُحجم بعض المستثمرين عن العمل في مجتمع تكثر فيه الجرائم؟","options":[{"id":"o1","text":"لخشيتهم على أموالهم نتيجة ضعف الأمن والاستقرار"},{"id":"o4","text":"لأن ارتفاع المخالفات يزيد الثقة بالضرورة"},{"id":"o3","text":"لأن الأمن لا يؤثر في النشاط الاقتصادي"},{"id":"o2","text":"لأن انتشار الجريمة يضمن حماية الأرباح"}],"correct_id":"o1","explanation":"ربط الكتاب بين ضعف الأمن وكثرة الجرائم وتراجع العمل والاستثمار.","page":154},{"id":"u04_l03_q119","lesson_id":"u04_l03","difficulty":"hard","prompt":"مؤسسة تعزز الأمانة وتحمي حقوق العاملين، وتُبلّغ الجهات المختصة عند مخالفة؛ أي نهج تجسده؟","options":[{"id":"o3","text":"الاكتفاء بإشاعة المخالفة بين الناس"},{"id":"o2","text":"تفويض كل موظف بتنفيذ العقوبة"},{"id":"o4","text":"ترك الحقوق دون حماية بحجة حسن النية"},{"id":"o1","text":"الجمع بين الوقاية الأخلاقية واحترام اختصاص الجهات القانونية"}],"correct_id":"o1","explanation":"يمدح الدرس الأخلاق والعدالة الاجتماعية، ويخص تنفيذ الجزاءات بالجهات المخولة.","page":156},{"id":"u04_l03_q124","lesson_id":"u04_l03","difficulty":"medium","prompt":"ما معيار إدراج الجريمة ضمن «الحدود» في تقسيم الفقه الإسلامي المعروض؟","options":[{"id":"o4","text":"كونها خلافًا عائليًا غير ذي أثر"},{"id":"o1","text":"ورود عقوبة مقدّرة لها شرعًا"},{"id":"o2","text":"ترك مقدار العقوبة لتقدير القاضي في كل مرة"},{"id":"o3","text":"اقتصارها على الأضرار المرورية"}],"correct_id":"o1","explanation":"تميّز جرائم الحدود بعقوبات مقدّرة في النص الشرعي، بخلاف التعزير.","page":154},{"id":"u04_l03_q129","lesson_id":"u04_l03","difficulty":"hard","prompt":"ما الخطر الذي يتجنبه المجتمع عندما تُحصر إقامة العقوبات بالجهات المختصة؟","options":[{"id":"o1","text":"الفوضى والاعتداء المتبادل الناتجان عن تصرف الأفراد من تلقاء أنفسهم"},{"id":"o3","text":"حماية حقوق الأفراد من التجاوز"},{"id":"o4","text":"وجود إجراءات واضحة لإثبات المخالفة"},{"id":"o2","text":"انتظام عمل المحاكم وفق القانون"}],"correct_id":"o1","explanation":"يؤكد الدرس أن تنفيذ العقوبات ليس للأفراد منعًا للفوضى والاعتداء على الحقوق.","page":157},{"id":"u04_l03_q130","lesson_id":"u04_l03","difficulty":"medium","prompt":"ما المقارنة الأدق بين «التدابير الوقائية» و«التدابير العلاجية» في مكافحة الجريمة؟","options":[{"id":"o2","text":"الأولى تنفذ العقوبات والثانية تمنع التعليم"},{"id":"o4","text":"كلتاهما تعنيان إقامة العقوبة قبل الفعل"},{"id":"o3","text":"الأولى خاصة بالقاضي والثانية خاصة بالأسرة فقط"},{"id":"o1","text":"الأولى تقلل دوافع وقوعها والثانية تتعامل مع الجريمة بعد حدوثها"}],"correct_id":"o1","explanation":"ميّز الدرس بين معالجة الأسباب قبل الجريمة والتعامل معها وما يترتب عليها بعد وقوعها.","page":157},{"id":"u04_l03_q133","lesson_id":"u04_l03","difficulty":"medium","prompt":"أي أثر اجتماعي للجريمة يتمثل في كثرة الخصومات والبغضاء بين الناس؟","options":[{"id":"o1","text":"إيقاع الفتن والعداوة بين أفراد المجتمع"},{"id":"o2","text":"تعزيز الثقة والطمأنينة"},{"id":"o3","text":"زيادة روح التعاون تلقائيًا"},{"id":"o4","text":"حماية استقرار الأسر"}],"correct_id":"o1","explanation":"عدّ الدرس إثارة الفتن والعداوة والبغضاء من أبرز آثار الجرائم.","page":153},{"id":"u04_l03_q136","lesson_id":"u04_l03","difficulty":"hard","prompt":"ما دلالة إناطة عقوبات جرائم التعزير برأي الدولة؟","options":[{"id":"o2","text":"ترك القرار لكل متضرر لينفذه بنفسه"},{"id":"o1","text":"مراعاة المصلحة وتنظيم العقوبة في الجرائم غير المحددة بعقوبة معينة"},{"id":"o3","text":"إلغاء دور الدولة والقضاء"},{"id":"o4","text":"تساوي جميع المخالفات في عقوبة محددة"}],"correct_id":"o1","explanation":"شرح الدرس أن عقوبات التعزير لم تحدد لها عقوبة بعينها وتُترك للجهات المختصة في الدولة.","page":155},{"id":"u04_l03_q138","lesson_id":"u04_l03","difficulty":"medium","prompt":"كيف يسهم التكافل الاجتماعي وتوفير فرص العمل في الوقاية من الجرائم؟","options":[{"id":"o1","text":"بمعالجة الحاجة وتخفيف بعض الأسباب التي قد تدفع إلى الاعتداء على المال"},{"id":"o4","text":"باعتبار الفقر سببًا يبيح الجريمة"},{"id":"o3","text":"بإضعاف المشاركة الاقتصادية"},{"id":"o2","text":"بالتشجيع على أخذ أموال الآخرين"}],"correct_id":"o1","explanation":"أشار الكتاب إلى العمل والتكافل الاجتماعي ضمن وسائل معالجة بعض أسباب الجريمة.","page":156},{"id":"u04_l03_q142","lesson_id":"u04_l03","difficulty":"medium","prompt":"لماذا يؤدي انتشار الجرائم إلى تراجع رغبة المستثمر في إقامة المشروعات؟","options":[{"id":"o3","text":"لأن المستثمر لا يحتاج إلى حماية المال"},{"id":"o2","text":"لأن الجرائم ترفع الثقة حتمًا"},{"id":"o1","text":"لخوفه على أمواله في بيئة تقل فيها الطمأنينة والاستقرار"},{"id":"o4","text":"لأن الجريمة تزيد الاستقرار الاقتصادي"}],"correct_id":"o1","explanation":"ربط الكتاب ضعف الاقتصاد بخشية التجار والمستثمرين على أموالهم عند اختلال الأمن.","page":153},{"id":"u04_l03_q144","lesson_id":"u04_l03","difficulty":"medium","prompt":"ما المعيار الأوضح الذي يميّز التعزير عن الحدود في التقسيم الفقهي للكتاب؟","options":[{"id":"o4","text":"تساوي كل العقوبات من حيث التحديد"},{"id":"o3","text":"انعدام تأثير التعزير في المجتمع"},{"id":"o1","text":"تقدير الجهة المختصة للعقوبة في التعزير وعدم تحديدها بعينها في النص الشرعي"},{"id":"o2","text":"اقتصار التعزير على مخالفات الصلاة"}],"correct_id":"o1","explanation":"عرّف الكتاب التعزير بالمعاصي التي لم تعين الشريعة لها عقوبة محددة وأوكلت تقديرها للدولة.","page":155},{"id":"u04_l03_q146","lesson_id":"u04_l03","difficulty":"hard","prompt":"طالب يبلغ عن خبر غير موثوق بدل نشره ويحرص على الوفاء بعهوده؛ أي تدبير وقائي تجتمع فيه أفعاله؟","options":[{"id":"o1","text":"تعزيز الجانب الأخلاقي وحفظ الثقة بين الناس"},{"id":"o2","text":"إلغاء دور الأنظمة الرسمية"},{"id":"o4","text":"الاستغناء عن الأخلاق أمام القانون"},{"id":"o3","text":"الاكتفاء بتصنيف الجرائم بعد وقوعها"}],"correct_id":"o1","explanation":"ذكر الدرس الصدق والأمانة والوفاء بالعهود من تدابير تعزيز الجانب الأخلاقي.","page":156},{"id":"u04_l03_q151","lesson_id":"u04_l03","difficulty":"medium","prompt":"ما القاسم الذي يجمع ارتكاب مخالفة ممنوعة وترك واجب في تعريف الجريمة المدرسي؟","options":[{"id":"o1","text":"مخالفة أمر شرعي رتّب عليه جزاء دنيويًا وأخرويًا"},{"id":"o3","text":"أن الجريمة لا تقع إلا بالاعتداء على الأموال"},{"id":"o4","text":"أن ترك الواجب لا يدخل في أي مخالفة"},{"id":"o2","text":"كونهما فعلين لا أثر لهما في المجتمع"}],"correct_id":"o1","explanation":"عرّف الكتاب الجريمة بمخالفة أوامر الشرع بالفعل أو الترك مما رُتبت عليه عقوبة.","page":153},{"id":"u04_l03_q156","lesson_id":"u04_l03","difficulty":"medium","prompt":"أي تدبير وقائي يسهم في خفض دوافع الاعتداء على ممتلكات الآخرين؟","options":[{"id":"o3","text":"تشجيع الاستغلال الاقتصادي"},{"id":"o2","text":"تعطيل الأعمال النافعة في المجتمع"},{"id":"o1","text":"توفير فرص العمل وبرامج التكافل لسد الحاجات"},{"id":"o4","text":"التهاون في أداء الأمانات"}],"correct_id":"o1","explanation":"ربط الدرس الوقاية من الاعتداء بالعمل والتكافل الاجتماعي ومعالجة أسبابه.","page":156}]$wall_questions$::jsonb)
